v=0; for f in package-lock.json npm-shrinkwrap.json yarn.lock pnpm-lock.yaml; do [ -e "$f" ] && v=1; done; [ -e bun.lock ] || v=1; { git diff HEAD -U0 | grep -E '^\+' | grep -vE '^\+\+\+ '; git ls-files --others --exclude-standard -z | xargs -0 -r cat 2>/dev/null; } | grep -qiE '(\bnpm (ci|i|install|run|test|exec|add)\b|\bnpx\b|\byarn\b|\bpnpm\b|cache: *npm|setup-node)' && v=1; [ $v = 1 ] && echo VIOLATED || echo OBEYED
